<script setup>
import { computed } from 'vue'
const props = defineProps({ task:Object, stats:Object, skills:Array, tools:Array })
const metrics = computed(() => props.stats?.metrics || {})
const toolsByCategory = computed(() => (props.tools || []).reduce((groups,t) => ((groups[t.category] ||= []).push(t),groups),{}))
</script>
<template><section class="panel detail"><div class="panel-title"><div><span class="eyebrow">TASK INSPECTOR</span><h2>执行详情</h2></div><span v-if="task" class="status" :class="task.status">{{ task.status }}</span></div><template v-if="task"><h3 class="goal">{{ task.goal }}</h3><div class="metric-strip"><div><b>{{ task.steps }}</b><small>执行步骤</small></div><div><b>{{ task.duration_ms == null ? '—' : (task.duration_ms/1000).toFixed(1)+'s' }}</b><small>耗时</small></div><div><b>{{ task.tokens || 0 }}</b><small>Tokens</small></div><div><b>{{ task.plan?.source || '—' }}</b><small>规划来源</small></div></div><div v-if="task.summary" class="result"><small>结果摘要</small><p>{{ task.summary }}</p></div><div v-if="task.error" class="alert">{{ task.error }}</div><h4>计划与执行</h4><div v-if="task.plan?.steps?.length" class="step-list"><div v-for="(s,i) in task.plan.steps" :key="i" class="step-row"><span class="step-num">{{ String(i+1).padStart(2,'0') }}</span><span>{{ s.description || s.tool }}</span><span class="muted">{{ s.status || 'pending' }}</span></div></div><div v-for="(s,i) in task.step_records" :key="'r'+i" class="record"><b>{{ s.tool }}</b><span>{{ s.observation || s.error }}</span></div><div v-if="task.evaluation?.criteria?.length" class="criteria"><span v-for="c in task.evaluation.criteria" :key="c.kind+c.value" :class="c.matched?'good-text':'bad-text'">{{ c.matched?'✓':'×' }} {{ c.kind }} · {{ c.value }}</span></div></template><div v-else class="empty detail-empty">选择一个任务查看计划、执行步骤和验证结果。</div><details class="fold"><summary>运行指标 <span>{{ metrics.episodes || 0 }} 条经验</span></summary><div class="mini-metrics"><span>成功率 <b>{{ metrics.success_rate == null ? '—' : (metrics.success_rate*100).toFixed(0)+'%' }}</b></span><span>平均步数 <b>{{ metrics.avg_steps ?? '—' }}</b></span><span>恢复率 <b>{{ metrics.recovery_rate == null ? '—' : (metrics.recovery_rate*100).toFixed(0)+'%' }}</b></span></div></details><details class="fold"><summary>技能库 <span>{{ skills?.length || 0 }}</span></summary><div v-for="s in skills" :key="s.name" class="skill-row"><b>{{ s.name }}</b><span>{{ s.uses }} 次 · {{ (s.success_rate*100).toFixed(0) }}% 成功</span></div><p v-if="!skills?.length" class="muted">成功任务会沉淀为可复用技能。</p></details><details class="fold"><summary>工具注册表 <span>{{ tools?.filter(t=>t.available).length || 0 }}/{{ tools?.length || 0 }} 可用</span></summary><div v-for="(items,cat) in toolsByCategory" :key="cat"><h5>{{ cat }}</h5><div v-for="tool in items" :key="tool.name" class="tool-row"><span :class="tool.available?'good-text':'bad-text'">●</span><b>{{ tool.name }}</b><small>{{ tool.description }}</small></div></div></details></section></template>
